<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($title??'Platform Administration') ?></title><style>
:root{--ink:#172033;--muted:#64748b;--line:#dbe2ea;--brand:#075985}*{box-sizing:border-box}body{font-family:Inter,system-ui,sans-serif;margin:0;color:var(--ink);background:#f3f6fa;line-height:1.5}.platform-nav{display:flex;gap:.5rem;padding:.9rem max(1rem,calc((100% - 76rem)/2));background:#111827}.platform-nav a{color:#fff;text-decoration:none;padding:.5rem .7rem}.platform-main{max-width:76rem;margin:auto;padding:1.4rem}a{color:var(--brand)}.page-head h1{margin:.1rem 0;font-size:clamp(1.8rem,4vw,2.5rem)}.page-head p,.muted,small{color:var(--muted)}.eyebrow{text-transform:uppercase;letter-spacing:.12em;font-weight:800;font-size:.75rem;color:var(--brand)!important}.panel{background:#fff;border:1px solid var(--line);padding:1.1rem;border-radius:.75rem}.split-grid,.admin-grid{display:grid;gap:1rem;grid-template-columns:repeat(auto-fit,minmax(20rem,1fr))}label{display:block;margin:.75rem 0;font-weight:650}input,select,textarea,button{font:inherit;width:100%;padding:.62rem;border:1px solid #b9c4d0;border-radius:.4rem}textarea{min-height:6rem}button,.button{display:inline-block;width:auto;background:var(--brand);color:#fff;border:0;padding:.65rem .9rem;border-radius:.4rem;text-decoration:none;font-weight:700}.button.secondary{background:#e2e8f0;color:#172033}.check{display:flex;gap:.5rem}.check input{width:auto}.notice,.error,.empty,.support-warning{padding:.8rem;margin:1rem 0;border-radius:.5rem}.notice{background:#ecfdf5}.error{background:#fef2f2;color:#991b1b}.empty{background:#f8fafc;color:var(--muted)}.support-warning{border:3px solid #b45309;background:#fffbeb}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:.7rem;border-bottom:1px solid var(--line)}.badge{display:inline-block;background:#e2e8f0;border-radius:99px;padding:.18rem .5rem;font-size:.8rem;text-transform:capitalize}.record-list{padding:0;list-style:none}.record-list li{padding:.55rem 0;border-bottom:1px solid var(--line)}@media(max-width:680px){.platform-main{padding:.8rem}table{min-width:36rem}}
</style></head><body data-layout="platform-admin"><nav class="platform-nav" aria-label="Platform administration"><a href="<?= site_url('platform/tenants') ?>">Schools</a><a href="<?= site_url('platform/support') ?>">Support access</a></nav><main class="platform-main"><?= $this->renderSection('content') ?></main></body></html>
